INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Budgetkalkulation nur für große Projekte wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Kostenkontrolle"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Budgetkalkulation?', 3, '[{"text": "Kosten abschätzen", "correct": true, "because": "Planung von Personal, Material, Zeit"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Planung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Budgetkalkulation?', 5, '[{"text": "Personalkosten", "correct": true, "because": "Arbeitsstunden abschätzen"}, {"text": "Materialkosten", "correct": true, "because": "Ressourcen berechnen"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Budgetkalkulation hilft bei der Ressourcenplanung. b) Sie ist nur für Finanzabteilungen nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Beteiligten nutzen sie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Budgetkalkulation?', 4, '[{"text": "Zeitaufwand", "correct": false, "because": "Bestimmt Personalkosten"}, {"text": "Materialbedarf", "correct": false, "because": "Wichtiger Kostenfaktor"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Budgetkalkulation auch Pufferkosten umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Für Unvorhergesehenes"}, {"text": "Nein", "correct": false, "because": "Teil guter Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist typisch für die Budgetkalkulation?', 3, '[{"text": "Stundensätze", "correct": true, "because": "Basis für Personalkosten"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zur Budgetkalkulation?', 5, '[{"text": "Zeitplanung", "correct": true, "because": "Beeinflusst Arbeitskosten"}, {"text": "Materialpreise", "correct": true, "because": "Bestimmt Ressourcenkosten"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Budgetkalkulation vermeidet Kostenüberschreitungen. b) Sie ist nur für den Projektstart nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontinuierlich angepasst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Budgetkalkulation?', 4, '[{"text": "Kostenabschätzung", "correct": false, "because": "Kern der Kalkulation"}, {"text": "Zeitaufwand", "correct": false, "because": "Bestimmt Personalkosten"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Budgetkalkulation nur für finanzielle Aspekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Zeit und Ressourcen"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Budgetkalkulation?', 4, '[{"text": "Top-Down-Abschätzung", "correct": true, "because": "Grobe Übersicht"}, {"text": "Bottom-Up-Abschätzung", "correct": true, "because": "Detaillierte Planung"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Budgetkalkulation nur grob sein muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Genauigkeit wichtig"}, {"text": "Ja", "correct": false, "because": "Detaillierte Planung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Budgetkalkulation?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Vermeidet Überschreitungen"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Schriftgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Budgetkalkulation umfasst Personalkosten. b) Sie ignoriert Materialkosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Materialkosten enthalten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Budgetkalkulation?', 5, '[{"text": "Stundensätze", "correct": true, "because": "Bestimmen Personalkosten"}, {"text": "Materialpreise", "correct": true, "because": "Wichtige Ressourcenkosten"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Budgetkalkulation unwichtig?', 3, '[{"text": "Zeitplan", "correct": false, "because": "Beeinflusst Kosten"}, {"text": "Ressourcenbedarf", "correct": false, "because": "Bestimmt Ausgaben"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Budgetkalkulation nur für den Projektstart?', 3, '[{"text": "Nein", "correct": true, "because": "Kontinuierlich angepasst"}, {"text": "Ja", "correct": false, "because": "Durchgehend relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Budgetkalkulation auch Puffer berücksichtigt?', 2, '[{"text": "Ja", "correct": true, "because": "Für Risiken und Unvorhergesehenes"}, {"text": "Nein", "correct": false, "because": "Teil der Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Budgetkalkulation?', 4, '[{"text": "Kostenabschätzung", "correct": true, "because": "Grundlage der Planung"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Kostenfokus"}]');
